@HandlerMachine.handler_machine_kernel
     : forall (MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF),
       Mixed.MixedMeasure MN MF ->
       forall FO : @Omega.SemanticOmega MF FI,
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       forall E F : Type -> Type,
       (forall X : Type, E X -> PTreeDefinition.ptree F MN X) ->
       forall A : Type,
       @HandlerMachine.handler_config E F MN A ->
       MF
         (PrimitiveStableHitting.stable_target (@HandlerMachine.handler_config E F MN A)
            (UnifiedFrontier.stable_head F MN A))

@HandlerMachine.handler_machine_complete_related
     : forall (E F MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI) (MX : Mixed.MixedMeasure MN MF)
         (FO : @Omega.SemanticOmega MF FI) (FOrd : @Omega.SemanticMeasureOrderLaws MF FI FO),
       @Omega.SemanticOmegaLaws MF FI FO ->
       forall Select : @Omega.SemanticOmegaSelection MF FI FO,
       @RelationalClosure.relational_bind MF FI ->
       forall (handler : forall X : Type, E X -> PTreeDefinition.ptree F MN X)
         (A B : Type) (RR : A -> B -> Prop),
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (c : @HandlerMachine.handler_config E F MN A)
         (d : @HandlerMachine.handler_config E F MN B)
         (mu : MF (UnifiedFrontier.stable_head F MN A))
         (nu : MF (UnifiedFrontier.stable_head F MN B)),
       @HandlerMachine.handler_config_rel E F MN MF FI FC MX FO A B RR c d ->
       @PrimitiveStableHitting.stable_hitting MF FI FO (@HandlerMachine.handler_config E F MN A)
         (UnifiedFrontier.stable_head F MN A)
         (@HandlerMachine.handler_machine_kernel MN MF FI MX FO FOrd Select E F handler A) c mu ->
       @PrimitiveStableHitting.stable_hitting MF FI FO (@HandlerMachine.handler_config E F MN B)
         (UnifiedFrontier.stable_head F MN B)
         (@HandlerMachine.handler_machine_kernel MN MF FI MX FO FOrd Select E F handler B) d nu ->
       @Measure.sem_lift MF FI (UnifiedFrontier.stable_head F MN A)
         (UnifiedFrontier.stable_head F MN B)
         (@PEutt.ptree_stable_head_rel F MN A B RR
            (@PEutt.bind_upto_closure F MN MF FI FC MX FO A B RR
               (@Preservation.interp_bisim_candidate E F MN MF FI FC MX FO A B RR handler))) mu nu

@HandlerMachineScheduling.handler_primitive_le_tree
     : forall (E F MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (handler : forall X : Type, E X -> PTreeDefinition.ptree F MN X)
         (A : Type) (n : nat) (c : @HandlerMachine.handler_config E F MN A),
       @Omega.sem_le MF FI FO (UnifiedFrontier.stable_head F MN A)
         (@HandlerMachineScheduling.handler_primitive_approx E F MN MF FI MX FO handler A n c)
         (@HandlerMachineScheduling.handler_tree_approx E F MN MF FI MX FO handler A n c)

@HandlerMachineScheduling.handler_tree_le_primitive
     : forall (E F MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (handler : forall X : Type, E X -> PTreeDefinition.ptree F MN X)
         (A : Type) (n : nat) (c : @HandlerMachine.handler_config E F MN A),
       @Omega.sem_le MF FI FO (UnifiedFrontier.stable_head F MN A)
         (@HandlerMachineScheduling.handler_tree_approx E F MN MF FI MX FO handler A n c)
         (@HandlerMachineScheduling.handler_primitive_approx E F MN MF FI MX FO handler A
            (2 * n + 2) c)

@HandlerMachineScheduling.handler_primitive_hitting_iff
     : forall (E F MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall handler : forall X : Type, E X -> PTreeDefinition.ptree F MN X,
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       forall (A : Type) (c : @HandlerMachine.handler_config E F MN A)
         (out : MF (UnifiedFrontier.stable_head F MN A)),
       @PrimitiveStableHitting.stable_hitting MF FI FO (@HandlerMachine.handler_config E F MN A)
         (UnifiedFrontier.stable_head F MN A)
         (@HandlerMachine.handler_primitive_kernel E F MN MF FI MX handler A) c out <->
       @PTreeKernel.ptree_stable_hitting F MN MF FI MX FO A
         (@PTreeDefinition.observe F MN A (@HandlerMachine.handler_config_tree E F MN handler A c))
         out

@HandlerMachineAcceleration.finite_head_bind_assoc
     : forall (MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (G : Type -> Type) (A B C : Type) (n : nat)
         (t : PTreeDefinition.ptreeF G MN A (PTreeDefinition.ptree G MN A))
         (k : UnifiedFrontier.stable_head G MN A -> MF B) (h : B -> MF C),
       @BindScheduling.equiv MF FI FO C
         (@Measure.sem_bind MF FI B C
            (@Measure.sem_bind MF FI (UnifiedFrontier.stable_head G MN A) B
               (@PTreeKernel.ptree_hitting_approx G MN MF FI MX FO A n t) k) h)
         (@Measure.sem_bind MF FI (UnifiedFrontier.stable_head G MN A) C
            (@PTreeKernel.ptree_hitting_approx G MN MF FI MX FO A n t)
            (fun x : UnifiedFrontier.stable_head G MN A => @Measure.sem_bind MF FI B C (k x) h))

@HandlerMachineAcceleration.handler_phase_grid_le_primitive
     : forall (E F MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall (handler : forall X : Type, E X -> PTreeDefinition.ptree F MN X)
         (A : Type) (n m : nat) (c : @HandlerMachine.handler_config E F MN A),
       @Omega.sem_le MF FI FO (UnifiedFrontier.stable_head F MN A)
         (@HandlerMachineAcceleration.handler_phase_grid E F MN MF FI MX FO handler A n m c)
         (@HandlerMachineScheduling.handler_primitive_approx E F MN MF FI MX FO handler A
            ((n + 1) * (m + 1)) c)

@HandlerMachineAcceleration.handler_primitive_le_phase_grid
