@HandlerMachineAcceleration.handler_phase_diagonal_hitting_iff
     : forall (E F MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall handler : forall X : Type, E X -> PTreeDefinition.ptree F MN X,
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       forall (A : Type) (c : @HandlerMachine.handler_config E F MN A)
         (out : MF (UnifiedFrontier.stable_head F MN A)),
       @Omega.sem_lub MF FI FO (UnifiedFrontier.stable_head F MN A)
         (fun n : nat =>
          @HandlerMachineAcceleration.handler_phase_grid E F MN MF FI MX FO handler A n n c) out <->
       @PrimitiveStableHitting.stable_hitting MF FI FO (@HandlerMachine.handler_config E F MN A)
         (UnifiedFrontier.stable_head F MN A)
         (@HandlerMachine.handler_primitive_kernel E F MN MF FI MX handler A) c out

@HandlerMachineAcceleration.handler_phase_grid_row_lub
     : forall (E F MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI)
         (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO)
         (handler : forall X : Type, E X -> PTreeDefinition.ptree F MN X),
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       forall (Select : @Omega.SemanticOmegaSelection MF FI FO) (A : Type)
         (n : nat) (c : @HandlerMachine.handler_config E F MN A),
       @Omega.sem_lub MF FI FO (UnifiedFrontier.stable_head F MN A)
         (fun m : nat =>
          @HandlerMachineAcceleration.handler_phase_grid E F MN MF FI MX FO handler A n m c)
         (@PrimitiveStableHitting.stable_hitting_approx MF FI FO
            (@HandlerMachine.handler_config E F MN A) (UnifiedFrontier.stable_head F MN A)
            (@HandlerMachine.handler_machine_kernel MN MF FI MX FO Ord Select E F handler A) n c)

@HandlerMachineAcceleration.handler_machine_hitting_sound
     : forall (E F MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI)
         (Ord : @Omega.SemanticMeasureOrderLaws MF FI FO),
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       forall handler : forall X : Type, E X -> PTreeDefinition.ptree F MN X,
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       forall (Select : @Omega.SemanticOmegaSelection MF FI FO) (A : Type)
         (c : @HandlerMachine.handler_config E F MN A)
         (out : MF (UnifiedFrontier.stable_head F MN A)),
       @PrimitiveStableHitting.stable_hitting MF FI FO (@HandlerMachine.handler_config E F MN A)
         (UnifiedFrontier.stable_head F MN A)
         (@HandlerMachine.handler_machine_kernel MN MF FI MX FO Ord Select E F handler A) c out ->
       @PTreeKernel.ptree_stable_hitting F MN MF FI MX FO A
         (@PTreeDefinition.observe F MN A (@HandlerMachine.handler_config_tree E F MN handler A c))
         out

