@Interp.Unrestricted.peutt_interp
     : forall (E F MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (handler : forall X : Type, E X -> PTreeDefinition.ptree F MN X)
         (A B : Type) (RR : A -> B -> Prop) (t : PTreeDefinition.ptree E MN A)
         (u : PTreeDefinition.ptree E MN B),
       @PEutt.peutt E MN MF FI FC MX FO A B RR t u ->
       @PEutt.peutt F MN MF FI FC MX FO A B RR (@PTreeDefinition.PTree.interp E F MN handler A t)
         (@PTreeDefinition.PTree.interp E F MN handler B u)

@Unrestricted.peutt_interp_Proper
     : forall (E F MN MF : Type -> Type) (FI : Measure.SemanticMeasure MF)
         (FC : @Measure.SemanticMeasureCoreLaws MF FI),
       @Measure.SemanticMeasureBindLaws MF FI ->
       forall (MX : Mixed.MixedMeasure MN MF) (FO : @Omega.SemanticOmega MF FI),
       @Omega.SemanticMeasureOrderLaws MF FI FO ->
       @Omega.SemanticOmegaLaws MF FI FO ->
       @Omega.SemanticOmegaCofinalityLaws MF FI FO ->
       @Omega.SemanticMeasureDiagonalLaws MF FI FO ->
       @Omega.SemanticOmegaFubiniLaws MF FI FO ->
       @BindOrder.SemanticMeasureBindOrderLaws MF FI FO ->
       @BindOrder.MixedMeasureBindOrderLaws MN MF FI MX FO ->
       @Omega.SemanticOmegaDirectedCofinalityLaws MF FI FO ->
       @Omega.SemanticOmegaSelection MF FI FO ->
       @RelationalClosure.relational_zero MF FI FO ->
       @RelationalClosure.relational_lub MF FI FO ->
       forall (handler : forall X : Type, E X -> PTreeDefinition.ptree F MN X) (A : Type),
       @Morphisms.Proper (PTreeDefinition.ptree E MN A -> PTreeDefinition.ptree F MN A)
         (@Morphisms.respectful (PTreeDefinition.ptree E MN A) (PTreeDefinition.ptree F MN A)
            (@PEutt.peutt E MN MF FI FC MX FO A A (@eq A))
            (@PEutt.peutt F MN MF FI FC MX FO A A (@eq A)))
         (@PTreeDefinition.PTree.interp E F MN handler A)

@UnrestrictedInterp.internally_returning_reader
     : forall (E : Type -> Type) (env : bool),
       @UnrestrictedInterp.reader_handler E env bool
         (@Sum.inl1 (Reader.readerE bool) E bool (@Reader.Ask bool)) =
       {|
         PTreeDefinition._observe :=
           @PTreeDefinition.RetF E Representation.SubEnumQ bool
             (PTreeDefinition.ptree E Representation.SubEnumQ bool) env
       |}
